@Test(timeout = 20000)
public void testTraceLatencyThresholdDynamicUpdate() throws InterruptedException {
    ConfigWatcherRegister register = new TraceLatencyThresholdMockConfigWatcherRegister(3);
    TraceSamplingPolicyWatcher watcher = new TraceSamplingPolicyWatcher(moduleConfig, provider);
    register.registerConfigChangeWatcher(watcher);
    register.start();
    // Default duration is -1, so 3000 must not be sampled,until updating to 3000
    while (!watcher.shouldSample("", 10000, 3000)) {
        Thread.sleep(2000);
    }
    Assert.assertTrue(watcher.shouldSample("", 10000, 3001));
}

@Test
public void testTraceLatencyThresholdNotify() {
    TraceSamplingPolicyWatcher watcher = new TraceSamplingPolicyWatcher(moduleConfig, provider);
    ConfigChangeWatcher.ConfigChangeEvent value1 = new ConfigChangeWatcher.ConfigChangeEvent("default:\n" + "  duration: 8000", ConfigChangeWatcher.EventType.MODIFY);
    watcher.notify(value1);
    globalDefaultDurationEquals(watcher, 8000);
    Assert.assertEquals(watcher.value(), "default:\n" + "  duration: 8000");
    ConfigChangeWatcher.ConfigChangeEvent value2 = new ConfigChangeWatcher.ConfigChangeEvent("default:\n" + "  duration: 8000", ConfigChangeWatcher.EventType.DELETE);
    watcher.notify(value2);
    Assert.assertEquals(watcher.value(), null);
    ConfigChangeWatcher.ConfigChangeEvent value3 = new ConfigChangeWatcher.ConfigChangeEvent("default:\n" + "  duration: 800", ConfigChangeWatcher.EventType.ADD);
    watcher.notify(value3);
    globalDefaultDurationEquals(watcher, 800);
    Assert.assertEquals(watcher.value(), "default:\n" + "  duration: 800");
    ConfigChangeWatcher.ConfigChangeEvent value4 = new ConfigChangeWatcher.ConfigChangeEvent("default:\n" + "  duration: abc", ConfigChangeWatcher.EventType.MODIFY);
    watcher.notify(value4);
    globalDefaultDurationEquals(watcher, 800);
    Assert.assertEquals(watcher.value(), "default:\n" + "  duration: 800");
    ConfigChangeWatcher.ConfigChangeEvent value5 = new ConfigChangeWatcher.ConfigChangeEvent("default:\n" + "  rate: abc\n" + "  duration: 900", ConfigChangeWatcher.EventType.MODIFY);
    watcher.notify(value5);
    globalDefaultDurationEquals(watcher, 800);
    Assert.assertEquals(watcher.value(), "default:\n" + "  duration: 800");
}

