    ImmutableMap<String, SampleFamily> input = ImmutableMap.of("http_success_request", SampleFamilyBuilder.newBuilder(Sample.builder().labels(of("idc", "t1")).value(50).build(), Sample.builder().labels(of("idc", "t3", "region", "cn", "svc", "catalog")).value(51).name("http_success_request").build(), Sample.builder().labels(of("idc", "t1", "region", "us", "svc", "product")).value(50).name("http_success_request").build(), Sample.builder().labels(of("idc", "t1", "region", "us", "instance", "10.0.0.1")).value(100).name("http_success_request").build(), Sample.builder().labels(of("idc", "t3", "region", "cn", "instance", "10.0.0.1")).value(3).name("http_success_request").build()).build());
    Map<String, AvgFunction> actValues = new HashMap<>();
    doAnswer(invocationOnMock -> {
        AvgFunction actValue = (AvgFunction) invocationOnMock.getArgument(0, AcceptableValue.class);
        actValues.put(actValue.getEntityId(), actValue);
        return null;
    }).when(meterSystem).doStreamingCalculation(any());
    analyzer.analyse(input);
    AvgFunction t1 = actValues.get(IDManager.ServiceInstanceID.buildId(IDManager.ServiceID.buildId("t1", true), ""));
    AvgFunction t1Us = actValues.get(IDManager.ServiceInstanceID.buildId(IDManager.ServiceID.buildId("t1", true), "us"));
    AvgFunction t3Cn = actValues.get(IDManager.ServiceInstanceID.buildId(IDManager.ServiceID.buildId("t3", true), "cn"));
    Assert.assertEquals(50L, t1.getSummation(), 0.0);
    Assert.assertEquals(1L, t1.getCount(), 0.0);
    Assert.assertEquals(150L, t1Us.getSummation(), 0.0);
    Assert.assertEquals(1L, t1Us.getCount(), 0.0);
    Assert.assertEquals(54L, t3Cn.getSummation(), 0.0);
    Assert.assertEquals(1L, t3Cn.getCount(), 0.0);
}

