@Test
public void match() {
    ContainMatch containMatch = new ContainMatch();
    Assert.assertFalse(containMatch.match(null, "http.method:GET"));
    Assert.assertTrue(containMatch.match(Arrays.asList("http.method:GET", "http.method:POST"), "http.method:GET"));
    Assert.assertFalse(containMatch.match(Arrays.asList("http.method:GET", "http.method:POST"), "http.method:PUT"));
}

@Test
public void testIn() {
    Assert.assertTrue(new InMatch().match("a", new Object[] { "\"a\"", "\"b\"" }));
    Assert.assertFalse(new InMatch().match("c", new Object[] { "\"a\"", "\"b\"" }));
    Assert.assertTrue(new InMatch().match(RequestType.RPC, new Object[] { RequestType.HTTP, RequestType.DATABASE, RequestType.RPC }));
    Assert.assertFalse(new InMatch().match(RequestType.gRPC, new Object[] { RequestType.HTTP, RequestType.DATABASE, RequestType.RPC }));
    Assert.assertTrue(new InMatch().match(1, new long[] { 1, 2, 3 }));
    Assert.assertFalse(new InMatch().match(4, new long[] { 1, 2, 3 }));
    Assert.assertTrue(new InMatch().match(1L, new long[] { 1, 2, 3 }));
    Assert.assertFalse(new InMatch().match(4L, new long[] { 1, 2, 3 }));
}

