    assertFalse(new LikeMatch().match("CarolineChanning", "Max%"));
    assertFalse(new LikeMatch().match("CarolineChanning", "%Max"));
    assertTrue(new LikeMatch().match("MaxBlack", "\"%Black\""));
    assertFalse(new LikeMatch().match("CarolineChanning", "\"Max%\""));
}

