@SuppressWarnings("unchecked")
@Test
public void testSearch() {
    final String index = "test-index";
    final Mappings.Source sourceConf = new Mappings.Source();
    sourceConf.getExcludes().add("key3");
    assertTrue(client.index().create(index, Mappings.builder().type("type").properties(ImmutableMap.of("key1", ImmutableMap.of("type", "keyword"))).properties(ImmutableMap.of("key2", ImmutableMap.of("type", "keyword"), "key3", ImmutableMap.of("type", "keyword"))).source(sourceConf).build(), null));
    final String type = "type";
    for (int i = 0; i < 10; i++) {
        client.documents().index(IndexRequest.builder().index(index).type(type).id("id" + i).doc(ImmutableMap.of("key1", "val" + i, "key2", "val" + (i + 1), "key3", "val" + (i + 2))).build(), null);
    }
    await().atMost(Duration.ONE_MINUTE).untilAsserted(() -> {
        SearchResponse response = client.search(Search.builder().query(Query.bool().must(Query.term("key1", "val1"))).build());
        assertEquals(1, response.getHits().getTotal());
        assertEquals("val1", response.getHits().iterator().next().getSource().get("key1"));
    });
    //test indexOnly
    await().atMost(Duration.ONE_MINUTE).untilAsserted(() -> {
        SearchResponse response = client.search(Search.builder().query(Query.bool().must(Query.term("key3", "val3"))).build());
        assertEquals(1, response.getHits().getTotal());
        assertEquals("val1", response.getHits().iterator().next().getSource().get("key1"));
        assertNull("indexOnly fields should not be stored", response.getHits().iterator().next().getSource().get("key3"));
    });
    await().atMost(Duration.ONE_MINUTE).pollInterval(Duration.FIVE_SECONDS).untilAsserted(() -> {
        SearchResponse response = client.search(Search.builder().query(Query.bool().must(Query.bool().should(Query.bool().must(Query.term("key1", "val1")).must(Query.term("key2", "val2")).build()).should(Query.bool().must(Query.term("key1", "val3")).must(Query.term("key2", "val4")).build()))).aggregation(Aggregation.terms("key1").field("key1.keyword").subAggregation(Aggregation.terms("key2").field("key2.keyword")).size(1000).build()).build());
        assertEquals(2, response.getHits().getTotal());
        assertEquals(1, response.getAggregations().size());
        assertEquals(2, ((List<?>) ((Map<String, ?>) response.getAggregations().get("key1")).get("buckets")).size());
    });
}

@Test
public void searchQueryShouldBeUpdatableAfterSet() {
    final BoolQueryBuilder queryBuilder = Query.bool();
    final SearchBuilder searchBuilder = Search.builder().query(queryBuilder);
    queryBuilder.must(Query.term("t", "v"));
    queryBuilder.should(Query.term("t", "v"));
    queryBuilder.mustNot(Query.term("t2", "v2"));
    queryBuilder.shouldNot(Query.term("t2", "v2"));
    queryBuilder.shouldNot(Query.term("t2", "v2"));
    final BoolQuery query = (BoolQuery) searchBuilder.build().getQuery();
    assertThat(query.getMust()).hasSize(1);
    assertThat(query.getShould()).hasSize(1);
    assertThat(query.getMustNot()).hasSize(1);
    assertThat(query.getShouldNot()).hasSize(2);
}

