@Test
public void resolveStructure() {
    IndexStructures structures = new IndexStructures();
    HashMap<String, Object> properties = new HashMap<>();
    properties.put("a", "b");
    properties.put("c", "d");
    structures.putStructure("test", Mappings.builder().type(ElasticSearchClient.TYPE).properties(properties).build());
    Mappings mapping = structures.getMapping("test");
    Assert.assertEquals(properties, mapping.getProperties());
    HashMap<String, Object> properties2 = new HashMap<>();
    properties2.put("a", "b");
    properties2.put("f", "g");
    structures.putStructure("test", Mappings.builder().type(ElasticSearchClient.TYPE).properties(properties2).build());
    mapping = structures.getMapping("test");
    HashMap<String, Object> res = new HashMap<>();
    res.put("a", "b");
    res.put("c", "d");
    res.put("f", "g");
    Assert.assertEquals(res, mapping.getProperties());
    //test with source
    IndexStructures structuresSource = new IndexStructures();
    Mappings.Source source = new Mappings.Source();
    source.getExcludes().addAll(Arrays.asList("a", "b", "c"));
    structuresSource.putStructure("test", Mappings.builder().type(ElasticSearchClient.TYPE).properties(properties).source(source).build());
    Assert.assertEquals(properties, structuresSource.getMapping("test").getProperties());
    Assert.assertEquals(source.getExcludes(), structuresSource.getMapping("test").getSource().getExcludes());
    Mappings.Source source2 = new Mappings.Source();
    source.getExcludes().addAll(Arrays.asList("b", "c", "d", "e"));
    structuresSource.putStructure("test", Mappings.builder().type(ElasticSearchClient.TYPE).properties(properties2).source(source2).build());
    Assert.assertEquals(res, structuresSource.getMapping("test").getProperties());
    Assert.assertEquals(new HashSet<>(), structuresSource.getMapping("test").getSource().getExcludes());
}

@Test
public void diffStructure() {
    IndexStructures structures = new IndexStructures();
    HashMap<String, Object> properties = new HashMap<>();
    properties.put("a", "b");
    properties.put("c", "d");
    properties.put("f", "g");
    structures.putStructure("test", Mappings.builder().type(ElasticSearchClient.TYPE).properties(properties).build());
    HashMap<String, Object> properties2 = new HashMap<>();
    properties2.put("a", "b");
    Mappings diffMappings = structures.diffStructure("test", Mappings.builder().type(ElasticSearchClient.TYPE).properties(properties2).build());
    HashMap<String, Object> res = new HashMap<>();
    res.put("c", "d");
    res.put("f", "g");
    Assert.assertEquals(res, diffMappings.getProperties());
    diffMappings = structures.diffStructure("test", Mappings.builder().type(ElasticSearchClient.TYPE).properties(properties).build());
    Assert.assertEquals(new HashMap<>(), diffMappings.getProperties());
    //test with source
    IndexStructures structuresSource = new IndexStructures();
    Mappings.Source source = new Mappings.Source();
    source.getExcludes().addAll(Arrays.asList("a", "b", "c"));
    structuresSource.putStructure("test", Mappings.builder().type(ElasticSearchClient.TYPE).properties(properties).source(source).build());
    diffMappings = structuresSource.diffStructure("test", Mappings.builder().type(ElasticSearchClient.TYPE).properties(properties2).source(source).build());
    Assert.assertEquals(res, diffMappings.getProperties());
    diffMappings = structuresSource.diffStructure("test", Mappings.builder().type(ElasticSearchClient.TYPE).properties(properties2).source(source).build());
    Assert.assertEquals(res, diffMappings.getProperties());
    Assert.assertNull("Mapping source should not be return by diffStructure()", diffMappings.getSource());
    diffMappings = structuresSource.diffStructure("test", Mappings.builder().type(ElasticSearchClient.TYPE).properties(properties).source(source).build());
    Assert.assertEquals(new HashMap<>(), diffMappings.getProperties());
}

